import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Tinkering","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/professions/tinkering.md","filePath":"en/guide/professions/tinkering.md"}'),n={name:"en/guide/professions/tinkering.md"};function s(d,e,o,l,c,h){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="tinkering" tabindex="-1">Tinkering <a class="header-anchor" href="#tinkering" aria-label="Permalink to &quot;Tinkering&quot;">​</a></h1><p><strong>Status:</strong> Proposed · New design not established as playable.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Tinkering understands and builds bounded precision mechanisms.</li><li>Diagnosis, repairs, traps and security create field roles.</li><li>Automation and future constructs need explicit limits and counterplay; no unlimited factories.</li></ul><p>Tinkering builds and understands precision mechanisms. Devices use bounded combinations of power, motion, triggers, control and output.</p><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Proposed role</th></tr></thead><tbody><tr><td>Processes</td><td>Inspect, design, assemble, calibrate, test, maintain</td></tr><tr><td>Field work</td><td>Diagnose traps, repair machinery, restore lifts or bridges</td></tr><tr><td>Security</td><td>Build/understand locks; Lockpicking defeats them</td></tr><tr><td>Journal</td><td>Observation and reverse engineering reveal clues</td></tr><tr><td>Training support</td><td>Candidate moving targets and practice mechanisms</td></tr></tbody></table><h2 id="progression-and-trade-offs" tabindex="-1">Progression and trade-offs <a class="header-anchor" href="#progression-and-trade-offs" aria-label="Permalink to &quot;Progression and trade-offs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Direction</th><th>Limit</th></tr></thead><tbody><tr><td>Disassemble unfamiliar device</td><td>Risk damage while learning</td></tr><tr><td>Traps with alchemical payloads</td><td>Require counterplay and clear rules</td></tr><tr><td>Housing gates, alarms, feeders</td><td>Bounded automation, not unlimited factories</td></tr><tr><td>Burglary</td><td>Detection and escalating risk; no trivial total house loss</td></tr><tr><td>Automatons / golems</td><td>Future specialization, no implemented system</td></tr></tbody></table><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>A tinkerer may diagnose a broken mechanism on an expedition instead of treating every device as a workshop recipe.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/professions/alchemy.html">Alchemy</a> · <a href="/Syrolands-Public/en/guide/professions/blacksmithing.html">Blacksmithing</a> · <a href="/Syrolands-Public/en/guide/characters/familiarity.html">Familiarity training</a> · <a href="/Syrolands-Public/en/guide/professions/overview.html">Shared learning</a> · <a href="/Syrolands-Public/en/game-design/professions/tinkering.html">Full specification</a></p><p><span id="what-it-does"></span><span id="why-take-it-into-the-field"></span><span id="learning-and-specialization"></span><span id="future-directions-and-limits"></span></p>',14)])])}const m=t(n,[["render",s]]);export{u as __pageData,m as default};
